//! Oracle fuzz test for the original function at 0x127b98 (generated by `factory gen`; the spec is the static
//! scan's inference: fix it here if the original faults or writes past a block). The port is `kh2_factory::ported::wrap_angle`.
//! Skips without a disc (KH2_ISO or local/iso.txt); fails without one when KH2_REQUIRE_DISC=1.

use kh2_factory::fuzz::*;

const SPEC: Spec = Spec {
    addr: 0x127b98,
    args: &[],
    floats: 1,
    ret: Ret::Float,
    globals: &[],
    stubs: &[],
    nulls: true,
};

#[test]
fn orig_127b98_matches_the_game() {
    let Some(st) = fuzz(&SPEC, 4000, |c| Out::float(kh2_factory::ported::wrap_angle(c.float(0)))) else { return };
    eprintln!("{} cases equal, {} interpreter steps in {:.3} s", st.cases, st.steps, st.secs);
}
